    'AxiX 交易所（前身为 WG Grid 交易平台，2026/08 正式更名）': 'AxiX Exchange (formerly WG Grid Trading Platform, officially renamed 2026/08)',
    'AIX 代币 K 线以 Akima + 单 tick 限幅平滑推进，强抑价格异动': 'AIX token K-lines advance smoothly via Akima + single-tick clamping, strongly suppressing price anomalies',
    '接口保持历史兼容；直推越多越省，50% 销毁 + 50% 进入 A10 分红池）；': 'the API stays backward compatible; the more direct referrals, the lower the fee — 50% burned + 50% into the A10 dividend pool);',
    '（A 为内部计价符号，用于接口层与撮合引擎兼容，实现细节对普通用户完全透明，无需关心）。': '(A is an internal pricing symbol kept for API and matching-engine compatibility; the detail is fully transparent to ordinary users and can be ignored).',
    '合约跟单对不同资产类别的做市、趋势、对冲子策略并行，72 分钟分位 slot 即兑现收益': 'Copy trading runs market-making, trend and hedging sub-strategies in parallel across asset classes, with yields credited per 72-minute slot',
    '以上为 2026/08 代币经济学预披露 v0.1，具体细则以 AxiX 官方后续公告为准。': 'The above is the 2026/08 tokenomics pre-disclosure v0.1; specifics are subject to subsequent official AxiX announcements.',
    '用户可在合约跟单页查看每个 slot 的 creditBalance 明细与排行榜对账': 'Users can view per-slot creditBalance details and leaderboard reconciliation on the Copy Trading page',
    '（例如不得使用「Aethon 艾克斯币」「Aethon 阿币」等组合），以避免造成品牌归属混淆。': '(e.g. combinations such as "Aethon Aix Coin" or "Aethon A-Coin" must not be used) to avoid brand-attribution confusion.',
    '覆盖 2,000+ 只股票的 9 项日频信号，0-100 分打分，由散户与机构资金流交互淬炼而成。': 'Covers 9 daily signals across 2,000+ stocks, scored 0–100, refined through the interplay of retail and institutional order flow.',
    'Profit Target / Stop Loss / Trailing Stop / Time Stop 四要素': 'Profit Target / Stop Loss / Trailing Stop / Time Stop — four elements',
    '因此任何 AIX 代币绝不能被表述为「Aethon 币 / Aethon 代币 / Aethon Fund 的代币」': 'Therefore no AIX token may ever be described as "Aethon Coin / Aethon Token / the token of Aethon Fund"',
    '代码符号仅用于后端撮合系统兼容，UI 上不再对用户展示，所有下单弹窗、余额 Pill、P&L 计算均以 AIX 为直观单位。': 'The code symbol exists only for backend matching-system compatibility and is no longer shown in the UI; all order dialogs, balance pills and P&L calculations use AIX as the intuitive unit.',
    '※ 若未来 Aethon Fund 出具明确书面反对，AxiX 品牌名与 AIX 代币名可在 48 小时内重新更名，不影响用户核心资产与合约。': '※ Should Aethon Fund issue a clear written objection in the future, the AxiX brand and AIX token names can be renamed within 48 hours without affecting users\' core assets or contracts.',
    '（最小精度 6 位小数，0.000001 AIX 起计价）。前端 UI 统一以「AIX」为显示单位，资产页、交易页、赚取页、钱包页均直接显示 AIX，不再出现任何内部代码符号的换算说明，避免混淆。': '(Minimum precision 6 decimals, priced from 0.000001 AIX). The frontend UI uniformly uses "AIX" as the display unit: assets, trading, earn and wallet pages all show AIX directly, with no internal code-symbol conversion notes, to avoid confusion.',
    'AxiX 交易所借鉴这一精神：合约跟单收益 72 分钟即入账而非每日结算，并在排行榜中以「已入账 reward + 合约名义量 + ROI 分母口径」三重交叉对账，向用户展示策略表现而非仅展示净值曲线。': 'AxiX Exchange draws on this spirit: copy-trading yields are credited every 72 minutes rather than settled daily, and the leaderboard triple cross-checks "credited reward + contract notional + ROI denominator" to show strategy performance instead of only a NAV curve.',
    '文档版本 v1.2 · 最后更新：2026-08-30 · 生效事项：项目更名 WG → AxiX / 代币代号 AXX → AIX（AIX = AxiX 三字母缩写）· 所有事实链接均已于当日核验可访问。': 'Document v1.2 · Last updated 2026-08-30 · Effective: project renamed WG → AxiX / token code AXX → AIX (AIX = three-letter abbreviation of AxiX) · all fact links verified accessible on that day.',
    '© 2026 AxiX 交易所 · AI 信号驱动 · 机构级风控 · 链上透明可查。本文档介绍平台策略方法论与 AIX 代币生态，具体功能与规则以平台内页面为准。': '© 2026 AxiX Exchange · AI signal-driven · institutional-grade risk control · on-chain transparency. This document introduces the platform strategy methodology and the AIX token ecosystem; actual features and rules as shown on in-platform pages.',

